# Fresh TPU notebook: attach original SEED1 v3 SegmentRetention step25000 endpoint + config.json. Internet on. 2000 paired updates; no test evaluation.
import base64, hashlib, pathlib, runpy, sys, zipfile, io
payload=base64.b64decode('')
assert hashlib.sha256(payload).hexdigest()=='8caf6bd88473cce3b29830f2aeaeec8bae59160c8b684688535b6281ae7b23f1'
ROOT=pathlib.Path('/kaggle/working/mx_two_stage_') / '8caf6bd88473cce3b29830f2aeaeec8bae59160c8b684688535b6281ae7b23f1'[:12]
ROOT.mkdir(parents=True,exist_ok=True)
with zipfile.ZipFile(io.BytesIO(payload)) as archive:
    for item in archive.infolist():
        if '/' in item.filename or '\\' in item.filename or item.filename in ('.','..'):
            raise ValueError('Unexpected package path')
        (ROOT/item.filename).write_bytes(archive.read(item))
import jax
jax.config.update('jax_default_matmul_precision','highest')
jax.clear_caches()
if jax.default_backend()!='tpu' or jax.device_count()!=8:
    raise RuntimeError('Select TPU in notebook accelerator settings, then restart the session.')
print('TWO_STAGE_TPU_READY',jax.__version__,jax.devices(),flush=True)
OUT=ROOT/'output'
OUT.mkdir(exist_ok=True)
old_argv=sys.argv[:]
old_path=sys.path[:]
names=('models','two_stage','segment_scale_trainer','run_probe','diagnose_drift','tpu_lm_train','enwik8_data')
saved={name:sys.modules.pop(name) for name in names if name in sys.modules}
try:
    sys.path.insert(0,str(ROOT))
    sys.argv=[str(ROOT/'replication_gate.py'),'--outdir',str(OUT)]
    # Use this process, so a second Python process does not compete for TPU ownership.
    runpy.run_path(str(ROOT/'replication_gate.py'),run_name='__main__')
finally:
    sys.argv=old_argv
    sys.path[:]=old_path
    for name in names:sys.modules.pop(name,None)
    sys.modules.update(saved)
    path=ROOT.parent/('mx_two_stage_'+'8caf6bd88473cce3b29830f2aeaeec8bae59160c8b684688535b6281ae7b23f1'[:12]+'_results.zip')
    with zipfile.ZipFile(path,'w',zipfile.ZIP_DEFLATED) as archive:
        for source in ROOT.rglob('*'):
            if source.is_file() and '__pycache__' not in source.parts and source.suffix != '.pkl':
                archive.write(source,source.relative_to(ROOT).as_posix())
    print('TWO_STAGE_RESULTS_ARCHIVE',path,flush=True)
